let itens = 0;

function adicionar() {
  itens = itens + 1;
  // ...e agora e voce quem lembra dos tres lugares
  document.querySelector("#topo").textContent = itens;
  document.querySelector("#total").textContent = itens;
  document.querySelector("#botao").disabled = itens === 0;
}

// quem escreve o componente RECEBE
function Saudacao({ nome }) {
  return <h1>Ola, {nome}</h1>;
}

// quem usa o componente PASSA, como se fosse tag
<Saudacao nome="Ada" />

